fn parser_semantics() -> &'static antlr4_runtime::ParserSemantics {
    static SEMANTICS_CELL: OnceLock<antlr4_runtime::ParserSemantics> = OnceLock::new();
    SEMANTICS_CELL.get_or_init(|| {
        let mut ir = antlr4_runtime::semir::SemIr::new();
        let mut predicates = Vec::new();
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::TokenIndexAdjacent);
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 238, pred_index: 17, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::TokenIndexAdjacent);
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 239, pred_index: 18, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::TokenIndexAdjacent);
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 239, pred_index: 19, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::TokenIndexAdjacent);
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 240, pred_index: 20, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::TokenIndexAdjacent);
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 241, pred_index: 21, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::TokenIndexAdjacent);
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 241, pred_index: 22, expr: __expr, failure_message: None });

        let actions = Vec::new();
        antlr4_runtime::ParserSemantics { ir, predicates, actions }
    })
}



/// Marker carried by generated contexts whose required-child
/// invariants were checked after a syntax-clean parse, and grammar brand of
/// this module's validated tree and rule-node types.
///
/// This marker stays module-local (unlike the runtime-owned support items)
/// so rustc can prove it never implements the runtime's
/// `__RecoveryContextState`, keeping the recovery-oriented and validated
/// accessor impls coherent — and so the runtime's branded validated types
/// stay nominally distinct per grammar.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ValidatedTreeContext {
    __private: (),
}

/// A completed, syntax-clean parse tree whose generated child cardinalities
/// have been structurally validated.
///
/// Alias of the runtime's grammar-agnostic `antlr4_runtime::ValidatedTree`
/// branded with this module's [`ValidatedTreeContext`] marker, so validated
/// trees of different grammars remain distinct types.
pub type CSharpValidatedTree = antlr4_runtime::ValidatedTree<ValidatedTreeContext>;

/// A rule node borrowed from a [`CSharpValidatedTree`].
///
/// Alias of the runtime's `antlr4_runtime::ValidatedRuleNode` branded with
/// this module's [`ValidatedTreeContext`] marker.
pub type ValidatedRuleNode<'a> = antlr4_runtime::ValidatedRuleNode<'a, ValidatedTreeContext>;

pub use antlr4_runtime::FromValidatedRuleNode;

/// Failure to recognize or validate a strict generated parse.
///
/// Alias of the grammar-agnostic `antlr4_runtime::ValidationError`; unlike
/// the branded tree types, the validation errors of every generated parser
/// are deliberately one shared type.
pub type CSharpValidationError = antlr4_runtime::ValidationError;

#[allow(dead_code)]
fn __context_kind(context: RuleNodeView<'_>) -> usize {
    context.rule_index()
}

#[allow(dead_code)]
fn __active_context_kind(
    context: &antlr4_runtime::ParserRuleContext,
    _storage: &antlr4_runtime::ParseTreeStorage,
    _tokens: &antlr4_runtime::TokenStore,
) -> usize {
    context.rule_index()
}

