#[allow(dead_code)]
pub struct CSharpTreeWalker;

#[allow(dead_code)]
impl CSharpTreeWalker {
    pub fn walk<E, T: CSharpListener<E>>(
        listener: &mut T,
        tree: antlr4_runtime::Node<'_>,
    ) -> Result<(), E> {
        Self::__walk(listener, tree, None)
    }

    pub fn walk_with_invocation_states<E, T: CSharpListener<E>>(
        listener: &mut T,
        tree: antlr4_runtime::Node<'_>,
        parent_invocation_states: Vec<isize>,
    ) -> Result<(), E> {
        Self::__walk(listener, tree, Some(parent_invocation_states))
    }

    fn __walk<E, T: CSharpListener<E>>(
        listener: &mut T,
        tree: antlr4_runtime::Node<'_>,
        invocation_states: Option<Vec<isize>>,
    ) -> Result<(), E> {
        let mut callbacks = __CSharpTreeWalkerCallbacks(listener);
        antlr4_runtime::generated::walk_generated(tree, invocation_states, &mut callbacks)
    }
}

pub type ParseTreeWalker = CSharpTreeWalker;

